import numpy as np
import matplotlib.pyplot as plt

import sys
import importlib

if 'whr_component' in sys.modules:
    del sys.modules['whr_component']

from tespy.networks import Network
from tespy.connections import Connection, PowerConnection
from tespy.components import (Source, Sink, PowerBus, PowerSink, HeatExchanger, SectionedHeatExchanger, Pump, CycleCloser, Condenser)
from whr_component import WasteHeatRecovery

cooling_system = Network(fluids = ["R134a"])

cooling_system.units.set_defaults(temperature = "degC", pressure = "bar", enthalpy = "kJ/kg", power = "kW", heat = "kW")

server_heat = Source("server heat")
server = Sink("server")
cd_cooling1 = Source("condenser cooling source")
cd_cooling2 = Sink("condenser cooling sink")

evaporator = HeatExchanger("adapted TPLT")
hx = SectionedHeatExchanger("V to L heat exchanger", num_sections = 50)
whr = WasteHeatRecovery("Efficient Seebeck-TEG")
hp = Pump("heat pump")
cc_one = CycleCloser("cycle closer one")
cc_two = CycleCloser("cycle closer two")
condenser = Condenser("Condenser")

energy_grid = PowerBus("Internal Microgrid", num_in=1, num_out=2)
surplus = PowerSink("surplus power")

c11 = Connection(server_heat, 'out1', evaporator, 'in1', label='11')
c12 = Connection(evaporator, 'out1', server, 'in1', label='12')

c1 = Connection(evaporator, 'out2', hx, 'in1', label='1')
c2 = Connection(hx, 'out1', cc_one, 'in1', label='2')
c13 = Connection(cc_one, 'out1', evaporator, 'in2', label='13')

c3 = Connection(hx, 'out2', whr, 'in1', label='3')
c4 = Connection(whr, 'out1', condenser, 'in1', label='4')
c5 = Connection(condenser, 'out1', hp, 'in1', label='5')
c6 = Connection(hp, 'out1', cc_two, 'in1')
c7 = Connection(cc_two, 'out1', hx, 'in2', label='7')

c21 = Connection(cd_cooling1, 'out1', condenser, 'in2', label='21')
c22 = Connection(condenser, 'out2', cd_cooling2, 'in1', label='22')

pc_whr = PowerConnection(whr, "power", energy_grid, "power_in1", label="teg_out")
pc_pump = PowerConnection(energy_grid, "power_out1", hp, "power", label="pump_in")
pc_surplus = PowerConnection(energy_grid, "power_out2", surplus, "power", label="surplus")

#cooling_system.add_conns(pc_whr, pc_pump)
cooling_system.add_conns(c11, c12, c13, c1, c2, c3, c4, c5, c6, c7, c21, c22)
cooling_system.add_conns(pc_whr, pc_pump, pc_surplus)

#fluid and attributes
evaporator.set_attr(pr1=0.98, pr2=1.0)
hx.set_attr(pr2=0.98)
condenser.set_attr(pr1=1.0, pr2=1.0)
c11.set_attr(T=50, p=10, m=1, fluid = {'R134a': 1})
c1.set_attr(p=8, x=1.0, m=1.0, fluid={'R134a': 1})  # ~31 °C — boils off a 38.6 °C source
c2.set_attr(x=0.0)
#x=0.0
whr.set_attr(pr=0.98, eta_teg=0.05)
c4.set_attr(x=0.9)
c3.set_attr(m=1.0)

#p=10.0
