import CoolProp.CoolProp as CP

#ambient heat reference conditions
T0_K = 20.0 + 273.15
p0_bar = 1.013

#h0 = CP.PropsSI("H", "T", T0_K, "P", p0_bar * 1e5, "R134a")/1000
#s0 = CP.PropsSI("S", "T", T0_K, "P", p0_bar * 1e5, "R134a")/1000

def get_exergy_change(conn_in, conn_out):
  m = conn_in.m.val
  h_in, h_out = conn_in.h.val/1000.0, conn_out.h.val/1000.0 #converting to kJ/kg rather than J/kg
  s_in, s_out = conn_in.s.val/1000.0, conn_out.s.val/1000.0

  return m * ((h_in - h_out) - T0_K * (s_in - s_out))

#Evaporator (Hot: c11 --> c12; Cold: c13 --> c1)
#E_11 = get_exergy(c11)
#E_12 = get_exergy(c12)
#E_13 = get_exergy(c13)
#E_1  = get_exergy(c1)

fuel_exergy_evap = get_exergy_change(c11, c12) #hot stream exergy loss
product_exergy_evap = -get_exergy_change(c13, c1) #cold stream exergy gain
eta_ex_evap = (product_exergy_evap/fuel_exergy_evap) * 100

#V-To-L Heat Exchanger (Hot: c1 --> c2; Cold: c7 --> c3)
#E_2 = get_exergy(c2)
#E_7 = get_exergy(c7)
#E_3 = get_exergy(c3)

fuel_exergy_hx = get_exergy_change(c1, c2) # Hot stream exergy loss
product_exergy_hx = -get_exergy_change(c7, c3) # Cold stream exergy gain
eta_ex_hx = (product_exergy_hx/ fuel_exergy_hx) * 100

e_server_supplied = fuel_exergy_evap
P_gen_out = abs(whr.P.val)  # Generator output power (kW)
P_pump_in = abs(hp.P.val) / 1000.0  # Convert to kW if in Watts

system_fuel_exergy = e_server_supplied + P_pump_in
system_product_exergy = P_gen_out
eta_ex_sys = (system_product_exergy / system_fuel_exergy) * 100

print(" ")
print("System Exergy Efficiency: ", eta_ex_sys)

