def solve_1d_heat_derivative(T_surface_fluid, q_heat_input, dt=0.001, total_steps=100):
    """
    Solves 1D heat diffusion using current system values.
    """
    k = 395.0  #Thermal conductivity (W/mK) - Copper
    rho = 8960.0 #Density (kg/m3)
    cp = 385.0 #Specific heat (J/kg K)
    alpha = k /(rho * cp) #alpha = thermal diffusivity

    L = 0.01        # Thickness (10 mm)
    Nx = 20         # Number of spatial nodes
    dx = L / (Nx - 1)

    # Calculate volumetric source from current system heat load
    domain_vol = 0.04 * 0.04 * L
    q_vol = q_heat_input / domain_vol

    # State array
    T = np.ones(Nx) * T_surface_fluid  # Initialize at current fluid temp

    for step in range(total_steps):
        T_new = T.copy()
        for i in range(1, Nx - 1):
            d2T_dx2 = (T[i+1] - 2*T[i] + T[i-1]) / (dx**2)
            T_new[i] = T[i] + dt * (alpha * d2T_dx2 + q_vol / (rho * cp))

        # Boundary Conditions linked to fluid loop
        T_new[0] = T_surface_fluid  # Left boundary tied to current fluid temp
        T_new[-1] = T_new[-2]       # Insulated right boundary
        T = T_new

    import matplotlib.pyplot as plt

    #Spatial temperature plotting
    x_coords = np.linspace(0, L * 1000, Nx)  # Convert meters to mm for display

    plt.figure(figsize=(8, 4.5))
    plt.plot(x_coords, T, color="crimson", linewidth=2, label="Temperature Profile")
    plt.title("1D Spatial Temperature Distribution")
    plt.xlabel("Position (mm)")
    plt.ylabel("Temperature (°C)")
    plt.grid(True, linestyle="--", alpha=0.6)
    plt.legend()
    plt.tight_layout()
    plt.show()

    # Before the loop: initialize tracking lists
    time_history = []
    midpoint_temp_history = []

    # Inside the time-stepping loop:
    for step in range(1000):
        # ... [your update logic here] ...

        # Record data every 10 steps
        if step % 10 == 0:
            time_history.append(step * dt)
            midpoint_temp_history.append(T_new[Nx // 2])  # Track center node

    # Plot transient response
    plt.plot(time_history, midpoint_temp_history, color="navy")
    plt.xlabel("Time (s)")
    plt.ylabel("Midpoint Temperature (°C)")
    plt.title("Midpoint Temperature vs. Time")
    plt.grid(True)
    plt.show()

    return T  # Return full temperature array across the domain

#call function
T_fluid = c1.T.val
Q_heat = c1.m.val * (c1.h.val_SI - c2.h.val_SI)

temperature_profile = solve_1d_heat_derivative(
    T_surface_fluid=T_fluid,
    q_heat_input=Q_heat,
    dt=0.001,
    total_steps=500
)

print("Temp. Profile:", temperature_profile)

