import numpy as np
import matplotlib.pyplot as plt
from matplotlib.patches import Rectangle

thick_cp = 2.0   # mm
thick_hx = 3.0  # mm
L_total = thick_cp + thick_hx # 5.0 mm total

Nx = 50
total_steps = 600
dt = 0.005  # seconds

# Generate real system values (Mocking 1D solver output)
x = np.linspace(0, L_total, Nx)
t = np.linspace(0, total_steps * dt, total_steps)
X, Y = np.meshgrid(x, t)

# Simulating thermal diffusion from R134a Evaporator (x=0) to HX Heat Sink (x=L)
T_evap = 65.0  # °C (Hot R134a vapor interface)
T_sink = 25.0  # °C (Coolant return)
T_matrix = np.zeros((total_steps, Nx))

for i, t_val in enumerate(t):
    steady_profile = T_evap - (T_evap - T_sink) * (x / L_total)**1.2
    transient_factor = 1 - np.exp(-t_val / 0.8)
    T_matrix[i, :] = 25.0 + (steady_profile - 25.0) * transient_factor

#Plot 1; 2D Heat Map with interference representation
fig, ax = plt.subplots(figsize=(9, 5.5))
heatmap = ax.pcolormesh(X, Y, T_matrix, cmap='plasma', shading='auto')
cbar = fig.colorbar(heatmap, ax=ax)
cbar.set_label('Solid Domain Temperature (°C)', rotation=270, labelpad=18, fontweight='bold')

#isotherm contour lines
contours = ax.contour(X, Y, T_matrix, levels=[35, 45, 55], colors='white', linestyles='--', linewidths=0.8)
ax.clabel(contours, inline=True, fmt='%1.0f °C', fontsize=8)

#component boundaries
ax.axvline(x=thick_cp, color='cyan', linestyle='-', linewidth=2, label='HX Cooling Wall -- Thermosyphon Interface')
ax.axhline(y=1.5, color='lime', linestyle=':', linewidth=1.5, label='Thermal Equilibrium Reached (~1.5s)')

#titles
ax.set_title('Transient Heat Diffusion: R134a Loop to HX Waste Heat Recovery', fontsize=12, pad=12, fontweight='bold')
ax.set_xlabel('Spatial Axis [0 = Evaporator Interface, 2mm = HX Hot Side] (mm)', fontweight='bold')
ax.set_ylabel('Time (s)', fontweight='bold')
ax.legend(loc='upper right', framealpha=0.9)
ax.grid(False)

plt.tight_layout()
plt.show()

#Plot 2; 3D Surface Thermal Map
fig3d = plt.figure(figsize=(10, 6.5))
ax3d = fig3d.add_subplot(111, projection='3d')
surf = ax3d.plot_surface(X, Y, T_matrix, cmap='plasma', edgecolor='none', alpha=0.85)
